249:         setSubscriptionType(SubscriptionType.USER_ASSIGNED);
250: 
251:         if (this.assignment.partitionSet().equals(partitions))
252:             return false;
253: 
254:         assignmentId++;
255: 
256:         // update the subscribed topics
257:         Set<String> manualSubscribedTopics = new HashSet<>();
258:         Map<TopicPartition, TopicPartitionState> partitionToState = new HashMap<>();
259:         for (TopicPartition partition : partitions) {
260:             TopicPartitionState state = assignment.stateValue(partition);
261:             if (state == null)
262:                 state = new TopicPartitionState();
263:             partitionToState.put(partition, state);
264: 
265:             manualSubscribedTopics.add(partition.topic());
266:         }
267: 
268:         this.assignment.set(partitionToState);
269:         return changeSubscription(manualSubscribedTopics);
