1032:         /**
1033:          * Check if the position exists and needs to be validated. If so, enter the AWAIT_VALIDATION state. This method
1034:          * also will update the position with the current leader and epoch.
1035:          *
1036:          * @param currentLeaderAndEpoch leader and epoch to compare the offset with
1037:          * @return true if the position is now awaiting validation
1038:          */
1039:         private boolean maybeValidatePosition(Metadata.LeaderAndEpoch currentLeaderAndEpoch) {
1040:             if (this.fetchState.equals(FetchStates.AWAIT_RESET)) {
1041:                 return false;
1042:             }
1043: 
1044:             if (currentLeaderAndEpoch.leader.isEmpty()) {
1045:                 return false;
1046:             }
1047: 
1048:             if (position != null && !position.currentLeader.equals(currentLeaderAndEpoch)) {
1049:                 FetchPosition newPosition = new FetchPosition(position.offset, position.offsetEpoch, currentLeaderAndEpoch);
1050:                 validatePosition(newPosition);
1051:                 preferredReadReplica = null;
1052:             }
1053:             return this.fetchState.equals(FetchStates.AWAIT_VALIDATION);
1054:         }
