985:         private void transitionState(FetchState newState, Runnable runIfTransitioned) {
986:             FetchState nextState = this.fetchState.transitionTo(newState);
987:             if (nextState.equals(newState)) {
988:                 this.fetchState = nextState;
989:                 runIfTransitioned.run();
990:                 if (this.position == null && nextState.requiresPosition()) {
991:                     throw new IllegalStateException("Transitioned subscription state to " + nextState + ", but position is null");
992:                 } else if (!nextState.requiresPosition()) {
993:                     this.position = null;
994:                 }
995:             }
996:         }
