1025:         private void reset(AutoOffsetResetStrategy strategy) {
1026:             transitionState(FetchStates.AWAIT_RESET, () -> {
1027:                 this.resetStrategy = strategy;
1028:                 this.nextRetryTimeMs = null;
1029:             });
1030:         }
