345:         this.updateVersion += 1;
346:         if (!isPartialUpdate) {
347:             this.needFullUpdate = false;
348:             this.lastSuccessfulRefreshMs = nowMs;
349:         }
350:         // If we subsequently find that the metadata response is not equivalent to the metadata already known,
351:         // this count is reset to 0 in updateLatestMetadata()
352:         this.equivalentResponseCount++;
353: 
354:         String previousClusterId = metadataSnapshot.clusterResource().clusterId();
355: 
356:         this.metadataSnapshot = handleMetadataResponse(response, isPartialUpdate, nowMs);
357: 
358:         Cluster cluster = metadataSnapshot.cluster();
359:         maybeSetMetadataError(cluster);
360: 
361:         this.lastSeenLeaderEpochs.keySet().removeIf(tp -> !retainTopic(tp.topic(), false, nowMs));
362: 
363:         String newClusterId = metadataSnapshot.clusterResource().clusterId();
364:         if (!Objects.equals(previousClusterId, newClusterId)) {
365:             log.info("Cluster ID: {}", newClusterId);
366:         }
367:         clusterResourceListeners.onUpdate(metadataSnapshot.clusterResource());
368: 
369:         log.debug("Updated cluster metadata updateVersion {} to {}", this.updateVersion, this.metadataSnapshot);
370:     }
