69:     private final ExponentialBackoff refreshBackoff;
70:     private final long metadataExpireMs;
71:     private int updateVersion;  // bumped on every metadata response
72:     private int requestVersion; // bumped on every new topic addition
73:     private long lastRefreshMs;
74:     private long lastSuccessfulRefreshMs;
75:     private long attempts;
76:     private KafkaException fatalException;
77:     private Set<String> invalidTopics;
78:     private Set<String> unauthorizedTopics;
79:     private volatile MetadataSnapshot metadataSnapshot = MetadataSnapshot.empty();
