92:      * @param refreshBackoffMs         The minimum amount of time that must expire between metadata refreshes to avoid busy
93:      *                                 polling
94:      * @param refreshBackoffMaxMs      The maximum amount of time to wait between metadata refreshes
95:      * @param metadataExpireMs         The maximum amount of time that metadata can be retained without refresh
96:      * @param logContext               Log context corresponding to the containing client
97:      * @param clusterResourceListeners List of ClusterResourceListeners which will receive metadata updates.
98:      */
99:     public Metadata(long refreshBackoffMs,
100:                     long refreshBackoffMaxMs,
101:                     long metadataExpireMs,
102:                     LogContext logContext,
103:                     ClusterResourceListeners clusterResourceListeners) {
104:         this.log = logContext.logger(Metadata.class);
105:         this.refreshBackoff = new ExponentialBackoff(
106:             refreshBackoffMs,
107:             CommonClientConfigs.RETRY_BACKOFF_EXP_BASE,
108:             refreshBackoffMaxMs,
109:             CommonClientConfigs.RETRY_BACKOFF_JITTER);
110:         this.metadataExpireMs = metadataExpireMs;
111:         this.lastRefreshMs = 0L;
112:         this.lastSuccessfulRefreshMs = 0L;
113:         this.attempts = 0L;
114:         this.requestVersion = 0;
115:         this.updateVersion = 0;
116:         this.needFullUpdate = false;
117:         this.needPartialUpdate = false;
118:         this.equivalentResponseCount = 0;
119:         this.clusterResourceListeners = clusterResourceListeners;
120:         this.isClosed = false;
121:         this.lastSeenLeaderEpochs = new HashMap<>();
122:         this.invalidTopics = Collections.emptySet();
123:         this.unauthorizedTopics = Collections.emptySet();
