372:     /**
373:      * Updates the partition-leadership info in the metadata. Update is done by merging existing metadata with the input leader information and nodes.
374:      * This is called whenever partition-leadership updates are returned in a response from broker(ex - ProduceResponse & FetchResponse).
375:      * Note that the updates via Metadata RPC are handled separately in ({@link #update}).
376:      * Both partitionLeader and leaderNodes override the existing metadata. Non-overlapping metadata is kept as it is.
377:      * @param partitionLeaders map of new leadership information for partitions.
378:      * @param leaderNodes a list of nodes for leaders in the above map.
379:      * @return a set of partitions, for which leaders were updated.
380:      */
381:     public synchronized Set<TopicPartition> updatePartitionLeadership(Map<TopicPartition, LeaderIdAndEpoch> partitionLeaders, List<Node> leaderNodes) {
382:         Map<Integer, Node> newNodes = leaderNodes.stream().collect(Collectors.toMap(Node::id, node -> node));
383:         // Insert non-overlapping nodes from existing-nodes into new-nodes.
384:         this.metadataSnapshot.cluster().nodes().forEach(node -> newNodes.putIfAbsent(node.id(), node));
385: 
386:         // Create partition-metadata for all updated partitions. Exclude updates for partitions -
387:         // 1. for which the corresponding partition has newer leader in existing metadata.
388:         // 2. for which corresponding leader's node is missing in the new-nodes.
389:         // 3. for which the existing metadata doesn't know about the partition.
390:         List<PartitionMetadata> updatePartitionMetadata = new ArrayList<>();
391:         for (Entry<TopicPartition, Metadata.LeaderIdAndEpoch> partitionLeader: partitionLeaders.entrySet()) {
392:             TopicPartition partition = partitionLeader.getKey();
393:             Metadata.LeaderAndEpoch currentLeader = currentLeader(partition);
394:             Metadata.LeaderIdAndEpoch newLeader = partitionLeader.getValue();
395:             if (newLeader.epoch.isEmpty() || newLeader.leaderId.isEmpty()) {
396:                 log.debug("For {}, incoming leader information is incomplete {}", partition, newLeader);
397:                 continue;
398:             }
399:             if (currentLeader.epoch.isPresent() && newLeader.epoch.get() <= currentLeader.epoch.get()) {
400:                 log.debug("For {}, incoming leader({}) is not-newer than the one in the existing metadata {}, so ignoring.", partition, newLeader, currentLeader);
401:                 continue;
402:             }
403:             if (!newNodes.containsKey(newLeader.leaderId.get())) {
404:                 log.debug("For {}, incoming leader({}), the corresponding node information for node-id {} is missing, so ignoring.", partition, newLeader, newLeader.leaderId.get());
405:                 continue;
406:             }
407:             if (this.metadataSnapshot.partitionMetadata(partition).isEmpty()) {
408:                 log.debug("For {}, incoming leader({}), partition metadata is no longer cached, ignoring.", partition, newLeader);
409:                 continue;
410:             }
411: 
412:             MetadataResponse.PartitionMetadata existingMetadata = this.metadataSnapshot.partitionMetadata(partition).get();
413:             MetadataResponse.PartitionMetadata updatedMetadata = new MetadataResponse.PartitionMetadata(
414:                 existingMetadata.error,
415:                 partition,
416:                 newLeader.leaderId,
417:                 newLeader.epoch,
418:                 existingMetadata.replicaIds,
419:                 existingMetadata.inSyncReplicaIds,
420:                 existingMetadata.offlineReplicaIds
421:             );
422:             updatePartitionMetadata.add(updatedMetadata);
423: 
424:             lastSeenLeaderEpochs.put(partition, newLeader.epoch.get());
425:         }
426: 
427:         if (updatePartitionMetadata.isEmpty()) {
428:             log.debug("No relevant metadata updates.");
429:             return new HashSet<>();
430:         }
431: 
432:         Set<String> updatedTopics = updatePartitionMetadata.stream().map(MetadataResponse.PartitionMetadata::topic).collect(Collectors.toSet());
433: 
434:         // Get topic-ids for updated topics from existing topic-ids.
435:         Map<String, Uuid> existingTopicIds = this.metadataSnapshot.topicIds();
436:         Map<String, Uuid> topicIdsForUpdatedTopics = updatedTopics.stream()
437:             .filter(existingTopicIds::containsKey)
438:             .collect(Collectors.toMap(e -> e, existingTopicIds::get));
439: 
440:         if (log.isDebugEnabled()) {
441:             updatePartitionMetadata.forEach(
442:                 partMetadata -> log.debug("For {} updating leader information, updated metadata is {}.", partMetadata.topicPartition, partMetadata)
443:             );
444:         }
445: 
446:         // Fetch responses can include partition level leader changes, when this happens, we perform a partial
447:         // metadata update, by keeping the unchanged partition and update the changed partitions.
448:         this.metadataSnapshot = metadataSnapshot.mergeWith(
449:             metadataSnapshot.clusterResource().clusterId(),
450:             newNodes,
451:             updatePartitionMetadata,
452:             Collections.emptySet(), Collections.emptySet(), Collections.emptySet(),
453:             metadataSnapshot.cluster().controller(),
454:             topicIdsForUpdatedTopics,
455:             (topic, isInternal) -> true);
456:         clusterResourceListeners.onUpdate(metadataSnapshot.clusterResource());
457: 
458:         return updatePartitionMetadata.stream()
459:             .map(metadata -> metadata.topicPartition)
460:             .collect(Collectors.toSet());
461:     }
