173:     /**
174:      * Update subscription state and metadata using the provided committed offsets:
175:      * <li>Update partition offsets with the committed offsets</li>
176:      * <li>Update the metadata with any newer leader epoch discovered in the committed offsets
177:      * metadata</li>
178:      * </p>
179:      * This will ignore any partition included in the <code>offsetsAndMetadata</code> parameter that
180:      * may no longer be assigned.
181:      *
182:      * @param offsetsAndMetadata Committed offsets and metadata to be used for updating the
183:      *                           subscription state and metadata object.
184:      * @param metadata           Metadata object to update with a new leader epoch if discovered in the
185:      *                           committed offsets' metadata.
186:      * @param subscriptions      Subscription state to update, setting partitions' offsets to the
187:      *                           committed offsets.
188:      */
189:     public static void refreshCommittedOffsets(final Map<TopicPartition, OffsetAndMetadata> offsetsAndMetadata,
190:                                                final ConsumerMetadata metadata,
191:                                                final SubscriptionState subscriptions) {
192:         for (final Map.Entry<TopicPartition, OffsetAndMetadata> entry : offsetsAndMetadata.entrySet()) {
193:             final TopicPartition tp = entry.getKey();
194:             final OffsetAndMetadata offsetAndMetadata = entry.getValue();
195:             if (offsetAndMetadata != null) {
196:                 // first update the epoch if necessary
197:                 entry.getValue().leaderEpoch().ifPresent(epoch -> metadata.updateLastSeenEpochIfNewer(entry.getKey(), epoch));
198: 
199:                 // it's possible that the partition is no longer assigned when the response is received,
200:                 // so we need to ignore seeking if that's the case
201:                 if (subscriptions.isAssigned(tp)) {
202:                     final ConsumerMetadata.LeaderAndEpoch leaderAndEpoch = metadata.currentLeader(tp);
203:                     final SubscriptionState.FetchPosition position = new SubscriptionState.FetchPosition(
204:                             offsetAndMetadata.offset(), offsetAndMetadata.leaderEpoch(),
205:                             leaderAndEpoch);
206: 
207:                     subscriptions.seekUnvalidated(tp, position);
208: 
209:                     log.info("Setting offset for partition {} to the committed offset {}", tp, position);
210:                 } else {
211:                     log.info("Ignoring the returned {} since its partition {} is no longer assigned",
212:                             offsetAndMetadata, tp);
213:                 }
214:             }
215:         }
216:     }
