709:     protected Map<String, Object> postProcessParsedConfig(final Map<String, Object> parsedValues) {
710:         CommonClientConfigs.postValidateSaslMechanismConfig(this);
711:         CommonClientConfigs.warnDisablingExponentialBackoff(this);
712:         Map<String, Object> refinedConfigs = CommonClientConfigs.postProcessReconnectBackoffConfigs(this, parsedValues);
713:         maybeOverrideClientId(refinedConfigs);
714:         maybeOverrideEnableAutoCommit(refinedConfigs);
715:         checkUnsupportedConfigsPostProcess();
716:         return refinedConfigs;
717:     }
