719:     private void maybeOverrideClientId(Map<String, Object> configs) {
720:         final String clientId = this.getString(CLIENT_ID_CONFIG);
721:         if (clientId == null || clientId.isEmpty()) {
722:             final String groupId = this.getString(GROUP_ID_CONFIG);
723:             String groupInstanceId = this.getString(GROUP_INSTANCE_ID_CONFIG);
724:             if (groupInstanceId != null)
725:                 JoinGroupRequest.validateGroupInstanceId(groupInstanceId);
726: 
727:             String groupInstanceIdPart = groupInstanceId != null ? groupInstanceId : CONSUMER_CLIENT_ID_SEQUENCE.getAndIncrement() + "";
728:             String generatedClientId = String.format("consumer-%s-%s", groupId, groupInstanceIdPart);
729:             configs.put(CLIENT_ID_CONFIG, generatedClientId);
730:         }
731:     }
