749:     private void maybeOverrideEnableAutoCommit(Map<String, Object> configs) {
750:         Optional<String> groupId = Optional.ofNullable(getString(CommonClientConfigs.GROUP_ID_CONFIG));
751:         Map<String, Object> originals = originals();
752:         boolean enableAutoCommit = originals.containsKey(ENABLE_AUTO_COMMIT_CONFIG) ? getBoolean(ENABLE_AUTO_COMMIT_CONFIG) : false;
753:         if (groupId.isEmpty()) { // overwrite in case of default group id where the config is not explicitly provided
754:             if (!originals.containsKey(ENABLE_AUTO_COMMIT_CONFIG)) {
755:                 configs.put(ENABLE_AUTO_COMMIT_CONFIG, false);
756:             } else if (enableAutoCommit) {
757:                 throw new InvalidConfigurationException(ENABLE_AUTO_COMMIT_CONFIG + " cannot be set to true when default group id (null) is used.");
758:             }
759:         }
760:     }
