27: /**
28:  * Ensures blocking APIs can be woken up by the consumer.wakeup().
29:  */
30: public class WakeupTrigger {
31:     private final AtomicReference<Wakeupable> pendingTask = new AtomicReference<>(null);
32: 
33:     /**
34:      * Wakeup a pending task.  If there isn't any pending task, return a WakeupFuture, so that the subsequent call
35:      * would know wakeup was previously called.
36:      * <p>
37:      * If there are active tasks, complete it with WakeupException, then unset pending task (return null here.
38:      * If the current task has already been woken-up, do nothing.
39:      */
40:     public void wakeup() {
41:         pendingTask.getAndUpdate(task -> {
42:             if (task == null) {
43:                 return new WakeupFuture();
44:             } else if (task instanceof ActiveFuture) {
45:                 ActiveFuture active = (ActiveFuture) task;
46:                 boolean wasTriggered = active.future().completeExceptionally(new WakeupException());
47: 
48:                 // If the Future was *already* completed when we invoke completeExceptionally, the WakeupException
49:                 // will be ignored. If it was already completed, we then need to return a new WakeupFuture so that the
50:                 // next call to setActiveTask will throw the WakeupException.
51:                 return wasTriggered ? null : new WakeupFuture();
52:             } else if (task instanceof FetchAction) {
53:                 FetchAction fetchAction = (FetchAction) task;
54:                 fetchAction.fetchBuffer().wakeup();
55:                 return new WakeupFuture();
56:             } else if (task instanceof ShareFetchAction) {
57:                 ShareFetchAction shareFetchAction = (ShareFetchAction) task;
58:                 shareFetchAction.fetchBuffer().wakeup();
59:                 return new WakeupFuture();
60:             } else {
61:                 return task;
62:             }
63:         });
64:     }
65: 
66:     /**
67:      *  If there is no pending task, set the pending task active.
68:      *  If wakeup was called before setting an active task, the current task will complete exceptionally with
69:      *  WakeupException right away.
70:      *  If there is an active task, throw exception.
71:      * @param currentTask
72:      * @param <T>
73:      * @return
74:      */
75:     public <T> CompletableFuture<T> setActiveTask(final CompletableFuture<T> currentTask) {
76:         Objects.requireNonNull(currentTask, "currentTask cannot be null");
77:         pendingTask.getAndUpdate(task -> {
78:             if (task == null) {
79:                 return new ActiveFuture(currentTask);
80:             } else if (task instanceof WakeupFuture) {
81:                 currentTask.completeExceptionally(new WakeupException());
82:                 return null;
83:             } else if (task instanceof DisabledWakeups) {
84:                 return task;
85:             }
86:             // last active state is still active
87:             throw new KafkaException("Last active task is still active");
88:         });
89:         return currentTask;
90:     }
91: 
92:     public void setFetchAction(final FetchBuffer fetchBuffer) {
93:         final AtomicBoolean throwWakeupException = new AtomicBoolean(false);
94:         pendingTask.getAndUpdate(task -> {
95:             if (task == null) {
96:                 return new FetchAction(fetchBuffer);
97:             } else if (task instanceof WakeupFuture) {
98:                 throwWakeupException.set(true);
99:                 return null;
100:             } else if (task instanceof DisabledWakeups) {
101:                 return task;
102:             }
103:             // last active state is still active
104:             throw new IllegalStateException("Last active task is still active");
105:         });
106:         if (throwWakeupException.get()) {
107:             throw new WakeupException();
108:         }
109:     }
110: 
111:     public void setShareFetchAction(final ShareFetchBuffer fetchBuffer) {
112:         final AtomicBoolean throwWakeupException = new AtomicBoolean(false);
113:         pendingTask.getAndUpdate(task -> {
114:             if (task == null) {
115:                 return new ShareFetchAction(fetchBuffer);
116:             } else if (task instanceof WakeupFuture) {
117:                 throwWakeupException.set(true);
118:                 return null;
119:             } else if (task instanceof DisabledWakeups) {
120:                 return task;
121:             }
122:             // last active state is still active
123:             throw new IllegalStateException("Last active task is still active");
124:         });
125:         if (throwWakeupException.get()) {
126:             throw new WakeupException();
127:         }
128:     }
129: 
130:     public void disableWakeups() {
131:         pendingTask.set(new DisabledWakeups());
132:     }
133: 
134:     public void clearTask() {
135:         pendingTask.getAndUpdate(task -> {
136:             if (task == null) {
137:                 return null;
138:             } else if (task instanceof ActiveFuture || task instanceof FetchAction || task instanceof ShareFetchAction) {
139:                 return null;
140:             }
141:             return task;
142:         });
143:     }
144: 
145:     public void maybeTriggerWakeup() {
146:         final AtomicBoolean throwWakeupException = new AtomicBoolean(false);
147:         pendingTask.getAndUpdate(task -> {
148:             if (task == null) {
149:                 return null;
150:             } else if (task instanceof WakeupFuture) {
151:                 throwWakeupException.set(true);
152:                 return null;
153:             } else {
154:                 return task;
155:             }
156:         });
157:         if (throwWakeupException.get()) {
158:             throw new WakeupException();
159:         }
160:     }
