589:     private void updateGroupSubscription(Set<String> topics) {
590:         // the leader will begin watching for changes to any of the topics the group is interested in,
591:         // which ensures that all metadata changes will eventually be seen
592:         if (this.subscriptions.groupSubscribe(topics))
593:             metadata.requestUpdateForNewTopics();
594: 
595:         // update metadata (if needed) and keep track of the metadata used for assignment so that
596:         // we can check after rebalance completion whether anything has changed
597:         if (!client.ensureFreshMetadata(time.timer(Long.MAX_VALUE)))
598:             throw new TimeoutException();
599: 
600:         maybeUpdateSubscriptionMetadata();
601:     }
