650:     @Override
651:     protected Map<String, ByteBuffer> onLeaderElected(String leaderId,
652:                                                       String assignmentStrategy,
653:                                                       List<JoinGroupResponseData.JoinGroupResponseMember> allSubscriptions,
654:                                                       boolean skipAssignment) {
655:         ConsumerPartitionAssignor assignor = lookupAssignor(assignmentStrategy);
656:         if (assignor == null)
657:             throw new IllegalStateException("Coordinator selected invalid assignment protocol: " + assignmentStrategy);
658:         String assignorName = assignor.name();
659: 
660:         Set<String> allSubscribedTopics = new HashSet<>();
661:         Map<String, Subscription> subscriptions = new HashMap<>();
662: 
663:         // collect all the owned partitions
664:         Map<String, List<TopicPartition>> ownedPartitions = new HashMap<>();
665: 
666:         for (JoinGroupResponseData.JoinGroupResponseMember memberSubscription : allSubscriptions) {
667:             Subscription subscription = ConsumerProtocol.deserializeSubscription(ByteBuffer.wrap(memberSubscription.metadata()));
668:             subscription.setGroupInstanceId(Optional.ofNullable(memberSubscription.groupInstanceId()));
669:             subscriptions.put(memberSubscription.memberId(), subscription);
670:             allSubscribedTopics.addAll(subscription.topics());
671:             ownedPartitions.put(memberSubscription.memberId(), subscription.ownedPartitions());
672:         }
673: 
674:         // the leader will begin watching for changes to any of the topics the group is interested in,
675:         // which ensures that all metadata changes will eventually be seen
676:         updateGroupSubscription(allSubscribedTopics);
677: 
678:         isLeader = true;
679: 
680:         if (skipAssignment) {
681:             log.info("Skipped assignment for returning static leader at generation {}. The static leader " +
682:                 "will continue with its existing assignment.", generation().generationId);
683:             assignmentSnapshot = metadataSnapshot;
684:             return Collections.emptyMap();
685:         }
686: 
687:         log.debug("Performing assignment using strategy {} with subscriptions {}", assignorName, subscriptions);
688: 
689:         Map<String, Assignment> assignments = assignor.assign(metadata.fetch(), new GroupSubscription(subscriptions)).groupAssignment();
690: 
691:         // skip the validation for built-in cooperative sticky assignor since we've considered
692:         // the "generation" of ownedPartition inside the assignor
693:         if (protocol == RebalanceProtocol.COOPERATIVE && !assignorName.equals(COOPERATIVE_STICKY_ASSIGNOR_NAME)) {
694:             validateCooperativeAssignment(ownedPartitions, assignments);
695:         }
696: 
697:         maybeUpdateGroupSubscription(assignorName, assignments, allSubscribedTopics);
698: 
699:         // metadataSnapshot could be updated when the subscription is updated therefore
700:         // we must take the assignment snapshot after.
701:         assignmentSnapshot = metadataSnapshot;
702: 
703:         log.info("Finished assignment for group at generation {}: {}", generation().generationId, assignments);
704: 
705:         Map<String, ByteBuffer> groupAssignment = new HashMap<>();
706:         for (Map.Entry<String, Assignment> assignmentEntry : assignments.entrySet()) {
707:             ByteBuffer buffer = ConsumerProtocol.serializeAssignment(assignmentEntry.getValue());
708:             groupAssignment.put(assignmentEntry.getKey(), buffer);
709:         }
710: 
711:         return groupAssignment;
712:     }
713: 
714:     /**
715:      * Used by COOPERATIVE rebalance protocol only.
716:      *
717:      * Validate the assignments returned by the assignor such that no owned partitions are going to
718:      * be reassigned to a different consumer directly: if the assignor wants to reassign an owned partition,
719:      * it must first remove it from the new assignment of the current owner so that it is not assigned to any
720:      * member, and then in the next rebalance it can finally reassign those partitions not owned by anyone to consumers.
721:      */
722:     private void validateCooperativeAssignment(final Map<String, List<TopicPartition>> ownedPartitions,
723:                                                final Map<String, Assignment> assignments) {
724:         Set<TopicPartition> totalRevokedPartitions = new HashSet<>();
725:         SortedSet<TopicPartition> totalAddedPartitions = new TreeSet<>(COMPARATOR);
726:         for (final Map.Entry<String, Assignment> entry : assignments.entrySet()) {
727:             final Assignment assignment = entry.getValue();
728:             final Set<TopicPartition> addedPartitions = new HashSet<>(assignment.partitions());
729:             addedPartitions.removeAll(ownedPartitions.get(entry.getKey()));
730:             final Set<TopicPartition> revokedPartitions = new HashSet<>(ownedPartitions.get(entry.getKey()));
731:             revokedPartitions.removeAll(assignment.partitions());
732: 
733:             totalAddedPartitions.addAll(addedPartitions);
734:             totalRevokedPartitions.addAll(revokedPartitions);
735:         }
736: 
737:         // if there are overlap between revoked partitions and added partitions, it means some partitions
738:         // immediately gets re-assigned to another member while it is still claimed by some member
739:         totalAddedPartitions.retainAll(totalRevokedPartitions);
740:         if (!totalAddedPartitions.isEmpty()) {
741:             log.error("With the COOPERATIVE protocol, owned partitions cannot be " +
742:                 "reassigned to other members; however the assignor has reassigned partitions {} which are still owned " +
743:                 "by some members", totalAddedPartitions);
