864:     private void maybeMarkPartitionsPendingRevocation() {
865:         if (protocol != RebalanceProtocol.EAGER) {
866:             return;
867:         }
868: 
869:         // When asynchronously committing offsets prior to the revocation of a set of partitions, there will be a
870:         // window of time between when the offset commit is sent and when it returns and revocation completes. It is
871:         // possible for pending fetches for these partitions to return during this time, which means the application's
872:         // position may get ahead of the committed position prior to revocation. This can cause duplicate consumption.
873:         // To prevent this, we mark the partitions as "pending revocation," which stops the Fetcher from sending new
874:         // fetches or returning data from previous fetches to the user.
875:         Set<TopicPartition> partitions = subscriptions.assignedPartitions();
876:         log.debug("Marking assigned partitions pending for revocation: {}", partitions);
877:         subscriptions.markPendingRevocation(partitions);
878:     }
