1097:     private RequestFuture<Void> doCommitOffsetsAsync(final Map<TopicPartition, OffsetAndMetadata> offsets, final OffsetCommitCallback callback) {
1098:         RequestFuture<Void> future = sendOffsetCommitRequest(offsets);
1099:         inFlightAsyncCommits.incrementAndGet();
1100:         final OffsetCommitCallback cb = callback == null ? defaultOffsetCommitCallback : callback;
1101:         future.addListener(new RequestFutureListener<>() {
1102:             @Override
1103:             public void onSuccess(Void value) {
1104:                 inFlightAsyncCommits.decrementAndGet();
1105: 
1106:                 if (interceptors != null)
1107:                     interceptors.onCommit(offsets);
1108:                 completedOffsetCommits.add(new OffsetCommitCompletion(cb, offsets, null));
1109:             }
1110: 
1111:             @Override
1112:             public void onFailure(RuntimeException e) {
1113:                 inFlightAsyncCommits.decrementAndGet();
1114: 
1115:                 Exception commitException = e;
1116: 
1117:                 if (e instanceof RetriableException) {
1118:                     commitException = new RetriableCommitFailedException(e);
1119:                 }
1120:                 completedOffsetCommits.add(new OffsetCommitCompletion(cb, offsets, commitException));
1121:                 if (commitException instanceof FencedInstanceIdException) {
