1512: 
1513:         @Override
1514:         public void handle(OffsetFetchResponse response, RequestFuture<Map<TopicPartition, OffsetAndMetadata>> future) {
1515:             var group = response.group(rebalanceConfig.groupId);
1516:             var groupError = Errors.forCode(group.errorCode());
1517: 
1518:             if (groupError != Errors.NONE) {
1519:                 log.debug("Offset fetch failed: {}", groupError.message());
1520: 
1521:                 if (groupError == Errors.COORDINATOR_NOT_AVAILABLE ||
1522:                     groupError == Errors.NOT_COORDINATOR) {
1523:                     // re-discover the coordinator and retry
1524:                     markCoordinatorUnknown(groupError);
1525:                     future.raise(groupError);
1526:                 } else if (groupError == Errors.GROUP_AUTHORIZATION_FAILED) {
1527:                     future.raise(GroupAuthorizationException.forGroupId(rebalanceConfig.groupId));
1528:                 } else if (groupError.exception() instanceof RetriableException) {
1529:                     // retry
1530:                     future.raise(groupError);
1531:                 } else {
1532:                     future.raise(new KafkaException("Unexpected error in fetch offset response: " + groupError.message()));
1533:                 }
1534:                 return;
1535:             }
1536: 
1537:             var offsets = new HashMap<TopicPartition, OffsetAndMetadata>();
1538:             var unstableTxnOffsetTopicPartitions = new HashSet<TopicPartition>();
1539:             var unauthorizedTopics = new HashSet<String>();
1540: 
1541:             for (var topic : group.topics()) {
1542:                 for (var partition : topic.partitions()) {
1543:                     var tp = new TopicPartition(
1544:                         topic.name(),
1545:                         partition.partitionIndex()
1546:                     );
1547:                     var error = Errors.forCode(partition.errorCode());
1548: 
1549:                     if (error != Errors.NONE) {
1550:                         log.debug("Failed to fetch offset for partition {}: {}", tp, error.message());
1551: 
1552:                         if (error == Errors.UNKNOWN_TOPIC_OR_PARTITION) {
1553:                             future.raise(new KafkaException("Topic or Partition " + tp + " does not exist"));
1554:                             return;
1555:                         } else if (error == Errors.TOPIC_AUTHORIZATION_FAILED) {
1556:                             unauthorizedTopics.add(tp.topic());
1557:                         } else if (error == Errors.UNSTABLE_OFFSET_COMMIT) {
1558:                             unstableTxnOffsetTopicPartitions.add(tp);
1559:                         } else {
1560:                             future.raise(new KafkaException("Unexpected error in fetch offset response for partition " +
1561:                                 tp + ": " + error.message()));
1562:                             return;
1563:                         }
1564:                     } else if (partition.committedOffset() >= 0) {
1565:                         // record the position with the offset (-1 indicates no committed offset to fetch);
