336:     private void doUpdateJoinedSubscriptionIfPatternSubscriptionChanged(Set<TopicPartition> assignedPartitions) {
337:         if (subscriptions.hasPatternSubscription()) {
338:             // Check if the assignment contains some topics that were not in the original
339:             // subscription, if yes we will obey what leader has decided and add these topics
340:             // into the subscriptions as long as they still match the subscribed pattern
341: 
342:             Set<String> addedTopics = new HashSet<>();
343:             // this is a copy because it's handed to listener below
344:             for (TopicPartition tp : assignedPartitions) {
345:                 if (!joinedSubscription.contains(tp.topic()))
346:                     addedTopics.add(tp.topic());
347:             }
348: 
349:             if (!addedTopics.isEmpty()) {
350:                 Set<String> newSubscription = new HashSet<>(subscriptions.subscription());
351:                 Set<String> newJoinedSubscription = new HashSet<>(joinedSubscription);
352:                 newSubscription.addAll(addedTopics);
353:                 newJoinedSubscription.addAll(addedTopics);
354: 
355:                 if (this.subscriptions.subscribeFromPattern(newSubscription))
356:                     metadata.requestUpdateForNewTopics();
357:                 this.joinedSubscription = newJoinedSubscription;
358:             }
359:         }
360:     }
