374:     @Override
375:     protected void onJoinComplete(int generation,
376:                                   String memberId,
377:                                   String assignmentStrategy,
378:                                   ByteBuffer assignmentBuffer) {
379:         log.debug("Executing onJoinComplete with generation {} and memberId {}", generation, memberId);
380: 
381:         // Only the leader is responsible for monitoring for metadata changes (i.e. partition changes)
382:         if (!isLeader)
383:             assignmentSnapshot = null;
384: 
385:         ConsumerPartitionAssignor assignor = lookupAssignor(assignmentStrategy);
386:         if (assignor == null)
387:             throw new IllegalStateException("Coordinator selected invalid assignment protocol: " + assignmentStrategy);
388: 
389:         // Give the assignor a chance to update internal state based on the received assignment
390:         groupMetadata = new ConsumerGroupMetadata(rebalanceConfig.groupId, generation, memberId, rebalanceConfig.groupInstanceId);
391: 
392:         SortedSet<TopicPartition> ownedPartitions = new TreeSet<>(COMPARATOR);
393:         ownedPartitions.addAll(subscriptions.assignedPartitions());
394: 
395:         // should at least encode the short version
396:         if (assignmentBuffer.remaining() < 2)
397:             throw new IllegalStateException("There are insufficient bytes available to read assignment from the sync-group response (" +
398:                 "actual byte size " + assignmentBuffer.remaining() + ") , this is not expected; " +
399:                 "it is possible that the leader's assign function is buggy and did not return any assignment for this member, " +
400:                 "or because static member is configured and the protocol is buggy hence did not get the assignment for this member");
401: 
402:         Assignment assignment = ConsumerProtocol.deserializeAssignment(assignmentBuffer);
403: 
404:         SortedSet<TopicPartition> assignedPartitions = new TreeSet<>(COMPARATOR);
405:         assignedPartitions.addAll(assignment.partitions());
406: 
407:         if (!subscriptions.checkAssignmentMatchedSubscription(assignedPartitions)) {
408:             final String fullReason = String.format("received assignment %s does not match the current subscription %s; " +
409:                     "it is likely that the subscription has changed since we joined the group, will re-join with current subscription",
410:                     assignment.partitions(), subscriptions.prettyString());
411:             requestRejoin("received assignment does not match the current subscription", fullReason);
412: 
413:             return;
414:         }
415: 
416:         final AtomicReference<Exception> firstException = new AtomicReference<>(null);
417:         SortedSet<TopicPartition> addedPartitions = new TreeSet<>(COMPARATOR);
418:         addedPartitions.addAll(assignedPartitions);
419:         addedPartitions.removeAll(ownedPartitions);
420: 
421:         if (protocol == RebalanceProtocol.COOPERATIVE) {
422:             SortedSet<TopicPartition> revokedPartitions = new TreeSet<>(COMPARATOR);
423:             revokedPartitions.addAll(ownedPartitions);
424:             revokedPartitions.removeAll(assignedPartitions);
425: 
426:             log.info("Updating assignment with\n" +
427:                     "\tAssigned partitions:                       {}\n" +
428:                     "\tCurrent owned partitions:                  {}\n" +
429:                     "\tAdded partitions (assigned - owned):       {}\n" +
430:                     "\tRevoked partitions (owned - assigned):     {}\n",
431:                 assignedPartitions,
432:                 ownedPartitions,
433:                 addedPartitions,
434:                 revokedPartitions
435:             );
436: 
437:             if (!revokedPartitions.isEmpty()) {
438:                 // Revoke partitions that were previously owned but no longer assigned;
439:                 // note that we should only change the assignment (or update the assignor's state)
440:                 // AFTER we've triggered  the revoke callback
441:                 firstException.compareAndSet(null, rebalanceListenerInvoker.invokePartitionsRevoked(revokedPartitions));
442: 
443:                 // If revoked any partitions, need to re-join the group afterwards
444:                 final String fullReason = String.format("need to revoke partitions %s as indicated " +
445:                         "by the current assignment and re-join", revokedPartitions);
446:                 requestRejoin("need to revoke partitions and re-join", fullReason);
447:             }
448:         }
449: 
450:         // The leader may have assigned partitions which match our subscription pattern, but which
451:         // were not explicitly requested, so we update the joined subscription here.
452:         doUpdateJoinedSubscriptionIfPatternSubscriptionChanged(assignedPartitions);
453: 
454:         // Catch any exception here to make sure we could complete the user callback.
455:         firstException.compareAndSet(null, invokeOnAssignment(assignor, assignment));
456: 
457:         // Reschedule the auto commit starting from now
458:         if (autoCommitEnabled)
459:             this.nextAutoCommitTimer.updateAndReset(autoCommitIntervalMs);
460: 
461:         subscriptions.assignFromSubscribed(assignedPartitions);
462: 
463:         // Add partitions that were not previously owned but are now assigned
464:         firstException.compareAndSet(null, rebalanceListenerInvoker.invokePartitionsAssigned(addedPartitions));
465: 
466:         if (firstException.get() != null) {
467:             if (firstException.get() instanceof KafkaException) {
468:                 throw (KafkaException) firstException.get();
469:             } else {
470:                 throw new KafkaException("User rebalance callback throws an error", firstException.get());
471:             }
472:         }
473:     }
