607:     /**
608:      * user-customized assignor may have created some topics that are not in the subscription list
609:      * and assign their partitions to the members; in this case we would like to update the leader's
610:      * own metadata with the newly added topics so that it will not trigger a subsequent rebalance
611:      * when these topics gets updated from metadata refresh.
612:      *
613:      * We skip the check for in-product assignors since this will not happen in in-product assignors.
614:      *
615:      * TODO: this is a hack and not something we want to support long-term unless we push regex into the protocol
616:      *       we may need to modify the ConsumerPartitionAssignor API to better support this case.
617:      *
618:      * @param assignorName          the selected assignor name
619:      * @param assignments           the assignments after assignor assigned
620:      * @param allSubscribedTopics   all consumers' subscribed topics
621:      */
622:     private void maybeUpdateGroupSubscription(String assignorName,
623:                                               Map<String, Assignment> assignments,
624:                                               Set<String> allSubscribedTopics) {
625:         if (!isAssignFromSubscribedTopicsAssignor(assignorName)) {
626:             Set<String> assignedTopics = new HashSet<>();
627:             for (Assignment assigned : assignments.values()) {
628:                 for (TopicPartition tp : assigned.partitions())
629:                     assignedTopics.add(tp.topic());
630:             }
631: 
632:             if (!assignedTopics.containsAll(allSubscribedTopics)) {
633:                 SortedSet<String> notAssignedTopics = new TreeSet<>(allSubscribedTopics);
634:                 notAssignedTopics.removeAll(assignedTopics);
635:                 log.warn("The following subscribed topics are not assigned to any members: {} ", notAssignedTopics);
636:             }
637: 
638:             if (!allSubscribedTopics.containsAll(assignedTopics)) {
639:                 SortedSet<String> newlyAddedTopics = new TreeSet<>(assignedTopics);
640:                 newlyAddedTopics.removeAll(allSubscribedTopics);
641:                 log.info("The following not-subscribed topics are assigned, and their metadata will be " +
642:                     "fetched from the brokers: {}", newlyAddedTopics);
643: 
644:                 allSubscribedTopics.addAll(newlyAddedTopics);
645:                 updateGroupSubscription(allSubscribedTopics);
646:             }
647:         }
648:     }
