880:     @Override
881:     public void onLeavePrepare() {
882:         // Save the current Generation, as the hb thread can change it at any time
883:         final Generation currentGeneration = generation();
884: 
885:         log.debug("Executing onLeavePrepare with generation {}", currentGeneration);
886: 
887:         // we should reset assignment and trigger the callback before leaving group
888:         SortedSet<TopicPartition> droppedPartitions = new TreeSet<>(COMPARATOR);
889:         droppedPartitions.addAll(subscriptions.assignedPartitions());
890: 
891:         if (subscriptions.hasAutoAssignedPartitions() && !droppedPartitions.isEmpty()) {
892:             final Exception e;
893:             if ((currentGeneration.generationId == Generation.NO_GENERATION.generationId ||
894:                 currentGeneration.memberId.equals(Generation.NO_GENERATION.memberId)) ||
895:                 rebalanceInProgress()) {
896:                 e = rebalanceListenerInvoker.invokePartitionsLost(droppedPartitions);
897:             } else {
898:                 e = rebalanceListenerInvoker.invokePartitionsRevoked(droppedPartitions);
899:             }
900: 
901:             subscriptions.assignFromSubscribed(Collections.emptySet());
902: 
903:             if (e != null) {
904:                 throw new KafkaException("User rebalance callback throws an error", e);
905:             }
906:         }
907:     }
