938:      * Refresh the committed offsets for partitions that require initialization.
939:      *
940:      * @param timer Timer bounding how long this method can block
941:      * @return true iff the operation completed within the timeout
942:      */
943:     public boolean initWithCommittedOffsetsIfNeeded(Timer timer) {
944:         final Set<TopicPartition> initializingPartitions = subscriptions.initializingPartitions();
945:         final Map<TopicPartition, OffsetAndMetadata> offsets = fetchCommittedOffsets(initializingPartitions, timer);
946: 
947:         // "offsets" will be null if the offset fetch requests did not receive responses within the given timeout
948:         if (offsets == null)
949:             return false;
950: 
951:         refreshCommittedOffsets(offsets, this.metadata, this.subscriptions);
952:         return true;
