1015:     public void close(final Timer timer, CloseOptions.GroupMembershipOperation membershipOperation) {
1016:         // we do not need to re-enable wakeups since we are closing already
1017:         client.disableWakeups();
1018:         try {
1019:             doAutoCommitOffsetsSyncIfEnabled(timer);
1020:             while (pendingAsyncCommits.get() > 0 && timer.notExpired()) {
1021:                 ensureCoordinatorReady(timer);
1022:                 client.poll(timer);
1023:                 invokeCompletedOffsetCommitCallbacks();
1024:             }
1025:         } finally {
1026:             super.close(timer, membershipOperation);
1027:         }
1028:     }
