1178:     private void doAutoCommitOffsetsSyncIfEnabled(Timer timer) {
1179:         if (autoCommitEnabled) {
1180:             Map<TopicPartition, OffsetAndMetadata> allConsumedOffsets = subscriptions.allConsumed();
1181:             try {
1182:                 log.debug("Sending synchronous auto-commit of offsets {}", allConsumedOffsets);
1183:                 if (!commitOffsetsSync(allConsumedOffsets, timer))
1184:                     log.debug("Auto-commit of offsets {} timed out before completion", allConsumedOffsets);
1185:             } catch (WakeupException | InterruptException e) {
1186:                 log.debug("Auto-commit of offsets {} was interrupted before completion", allConsumedOffsets);
1187:                 // rethrow wakeups since they are triggered by the user
1188:                 throw e;
1189:             } catch (Exception e) {
1190:                 // consistent with async auto-commit failures, we do not propagate the exception
1191:                 log.warn("Synchronous auto-commit of offsets {} failed: {}", allConsumedOffsets, e.getMessage());
1192:             }
1193:         }
1194:     }
