1389:                             future.raise(error);
1390:                             return;
1391:                         } else if (error == Errors.COORDINATOR_NOT_AVAILABLE
1392:                                 || error == Errors.NOT_COORDINATOR
1393:                                 || error == Errors.REQUEST_TIMED_OUT) {
1394:                             markCoordinatorUnknown(error);
1395:                             future.raise(error);
1396:                             return;
1397:                         } else if (error == Errors.FENCED_INSTANCE_ID) {
1398:                             log.info("OffsetCommit failed with {} due to group instance id {} fenced", sentGeneration, rebalanceConfig.groupInstanceId);
1399: 
1400:                             // if the generation has changed or we are not in rebalancing, do not raise the fatal error but rebalance-in-progress
1401:                             if (generationUnchanged()) {
1402:                                 future.raise(error);
1403:                             } else {
1404:                                 KafkaException exception;
1405:                                 synchronized (ConsumerCoordinator.this) {
1406:                                     if (ConsumerCoordinator.this.state == MemberState.PREPARING_REBALANCE) {
1407:                                         exception = new RebalanceInProgressException("Offset commit cannot be completed since the " +
1408:                                             "consumer member's old generation is fenced by its group instance id, it is possible that " +
1409:                                             "this consumer has already participated another rebalance and got a new generation");
