651:     // ArgumentCaptor's type-matching does not work reliably with Java 8, so we cannot directly capture the AsyncCommitEvent
652:     // Instead, we capture the super-class CompletableApplicationEvent and fetch the last captured event.
653:     private <T> CompletableApplicationEvent<T> getLastEnqueuedEvent() {
654:         final ArgumentCaptor<CompletableApplicationEvent<T>> eventArgumentCaptor = ArgumentCaptor.forClass(CompletableApplicationEvent.class);
655:         verify(applicationEventHandler, atLeast(1)).add(eventArgumentCaptor.capture());
656:         final List<CompletableApplicationEvent<T>> allValues = eventArgumentCaptor.getAllValues();
657:         return allValues.get(allValues.size() - 1);
658:     }
659: 
660:     private <T> CompletableApplicationEvent<T> addAndGetLastEnqueuedEvent() {
661:         final ArgumentCaptor<CompletableApplicationEvent<T>> eventArgumentCaptor = ArgumentCaptor.forClass(CompletableApplicationEvent.class);
662:         verify(applicationEventHandler, atLeast(1)).addAndGet(eventArgumentCaptor.capture());
663:         final List<CompletableApplicationEvent<T>> allValues = eventArgumentCaptor.getAllValues();
664:         return allValues.get(allValues.size() - 1);
665:     }
