1456:     /**
1457:      * Tests that the consumer correctly invokes the callbacks for {@link ConsumerRebalanceListener} that was
1458:      * specified. We don't go through the full effort to emulate heartbeats and correct group management here. We're
1459:      * simply exercising the background {@link EventProcessor} does the correct thing when
1460:      * {@link AsyncKafkaConsumer#poll(Duration)} is called.
1461:      *
1462:      * Note that we test {@link ConsumerRebalanceListener} that throws errors in its different callbacks. Failed
1463:      * callback execution does <em>not</em> immediately errors. Instead, those errors are forwarded to the
1464:      * application event thread for the {@link ConsumerMembershipManager} to handle.
1465:      */
1466:     @ParameterizedTest
1467:     @MethodSource("listenerCallbacksInvokeSource")
1468:     public void testListenerCallbacksInvoke(List<ConsumerRebalanceListenerMethodName> methodNames,
1469:                                             Optional<RuntimeException> revokedError,
1470:                                             Optional<RuntimeException> assignedError,
1471:                                             Optional<RuntimeException> lostError,
1472:                                             int expectedRevokedCount,
1473:                                             int expectedAssignedCount,
1474:                                             int expectedLostCount,
1475:                                             Optional<RuntimeException> expectedException
1476:                                             ) {
1477:         consumer = newConsumer();
1478:         CounterConsumerRebalanceListener consumerRebalanceListener = new CounterConsumerRebalanceListener(
1479:                 revokedError,
1480:                 assignedError,
1481:                 lostError
1482:         );
1483:         doReturn(Fetch.empty()).when(fetchCollector).collectFetch(any(FetchBuffer.class));
1484:         completeTopicSubscriptionChangeEventSuccessfully();
1485:         consumer.subscribe(Collections.singletonList("topic"), consumerRebalanceListener);
1486:         SortedSet<TopicPartition> partitions = Collections.emptySortedSet();
1487: 
1488:         for (ConsumerRebalanceListenerMethodName methodName : methodNames) {
1489:             CompletableBackgroundEvent<Void> e = new ConsumerRebalanceListenerCallbackNeededEvent(methodName, partitions);
1490:             backgroundEventQueue.add(e);
1491:         }
1492: 
1493:         markReconcileAndAutoCommitCompleteForPollEvent();
1494:         // This will trigger the background event queue to process our background event message.
1495:         // If any error is happening inside the rebalance callbacks, we expect the first exception to be thrown from poll.
1496:         if (expectedException.isPresent()) {
1497:             Exception exception = assertThrows(expectedException.get().getClass(), () -> consumer.poll(Duration.ZERO));
1498:             assertEquals(expectedException.get().getMessage(), exception.getMessage());
1499:             assertEquals(expectedException.get().getCause(), exception.getCause());
1500:         } else {
1501:             when(applicationEventHandler.addAndGet(any(CheckAndUpdatePositionsEvent.class))).thenReturn(true);
1502:             assertDoesNotThrow(() -> consumer.poll(Duration.ZERO));
1503:         }
1504: 
1505:         assertEquals(expectedRevokedCount, consumerRebalanceListener.revokedCount());
1506:         assertEquals(expectedAssignedCount, consumerRebalanceListener.assignedCount());
1507:         assertEquals(expectedLostCount, consumerRebalanceListener.lostCount());
1508:     }
1509: 
1510:     private static Stream<Arguments> listenerCallbacksInvokeSource() {
1511:         Optional<RuntimeException> empty = Optional.empty();
1512:         Optional<RuntimeException> error = Optional.of(new RuntimeException("Intentional error"));
1513:         Optional<RuntimeException> kafkaException = Optional.of(new KafkaException("Intentional error"));
1514:         Optional<RuntimeException> wrappedException = Optional.of(new KafkaException("User rebalance callback throws an error", error.get()));
1515: 
1516:         return Stream.of(
1517:             // Tests if we don't have an event, the listener doesn't get called.
1518:             Arguments.of(Collections.emptyList(), empty, empty, empty, 0, 0, 0, empty),
1519: 
1520:             // Tests if we get an event for a revocation, that we invoke our listener.
1521:             Arguments.of(Collections.singletonList(ON_PARTITIONS_REVOKED), empty, empty, empty, 1, 0, 0, empty),
1522: 
1523:             // Tests if we get an event for an assignment, that we invoke our listener.
1524:             Arguments.of(Collections.singletonList(ON_PARTITIONS_ASSIGNED), empty, empty, empty, 0, 1, 0, empty),
1525: 
1526:             // Tests that we invoke our listener even if it encounters an exception.
1527:             Arguments.of(Collections.singletonList(ON_PARTITIONS_LOST), empty, empty, empty, 0, 0, 1, empty),
1528: 
1529:             // Tests that we invoke our listener even if it encounters an exception.
1530:             Arguments.of(Collections.singletonList(ON_PARTITIONS_REVOKED), error, empty, empty, 1, 0, 0, wrappedException),
1531: 
1532:             // Tests that we invoke our listener even if it encounters an exception.
1533:             Arguments.of(Collections.singletonList(ON_PARTITIONS_ASSIGNED), empty, error, empty, 0, 1, 0, wrappedException),
1534: 
1535:             // Tests that we invoke our listener even if it encounters an exception.
1536:             Arguments.of(Collections.singletonList(ON_PARTITIONS_LOST), empty, empty, error, 0, 0, 1, wrappedException),
1537: 
1538:             // Tests that we invoke our listener even if it encounters an exception. Special case to test that a kafka exception is not wrapped.
1539:             Arguments.of(Collections.singletonList(ON_PARTITIONS_REVOKED), kafkaException, empty, empty, 1, 0, 0, kafkaException),
1540:             Arguments.of(Collections.singletonList(ON_PARTITIONS_ASSIGNED), empty, kafkaException, empty, 0, 1, 0, kafkaException),
1541:             Arguments.of(Collections.singletonList(ON_PARTITIONS_LOST), empty, empty, kafkaException, 0, 0, 1, kafkaException),
1542: 
1543:             // Tests if we get separate events for revocation and then assignment--AND our revocation throws an error--
1544:             // we still invoke the listeners correctly and throw the error.
1545:             Arguments.of(Arrays.asList(ON_PARTITIONS_REVOKED, ON_PARTITIONS_ASSIGNED), error, empty, empty, 1, 1, 0, wrappedException),
1546: 
1547:             // Tests if we get separate events for revocation and then assignment--AND both throws an error--
1548:             // we still invoke the listeners correctly and throw the first error.
1549:             Arguments.of(Arrays.asList(ON_PARTITIONS_REVOKED, ON_PARTITIONS_ASSIGNED), kafkaException, error, empty, 1, 1, 0, kafkaException)
1550:         );
1551:     }
