972:     @Override
973:     public void seek(TopicPartition partition, long offset) {
974:         if (offset < 0)
975:             throw new IllegalArgumentException("seek offset must not be a negative number");
976: 
977:         acquireAndEnsureOpen();
978:         try {
979:             log.info("Seeking to offset {} for partition {}", offset, partition);
980:             SeekUnvalidatedEvent seekUnvalidatedEventEvent = new SeekUnvalidatedEvent(
981:                 defaultApiTimeoutDeadlineMs(),
982:                 partition,
983:                 offset,
984:                 Optional.empty()
985:             );
986:             applicationEventHandler.addAndGet(seekUnvalidatedEventEvent);
987:         } finally {
988:             release();
989:         }
990:     }
