992:     @Override
993:     public void seek(TopicPartition partition, OffsetAndMetadata offsetAndMetadata) {
994:         long offset = offsetAndMetadata.offset();
995:         if (offset < 0) {
996:             throw new IllegalArgumentException("seek offset must not be a negative number");
997:         }
998: 
999:         acquireAndEnsureOpen();
1000:         try {
1001:             if (offsetAndMetadata.leaderEpoch().isPresent()) {
1002:                 log.info("Seeking to offset {} for partition {} with epoch {}",
1003:                     offset, partition, offsetAndMetadata.leaderEpoch().get());
1004:             } else {
1005:                 log.info("Seeking to offset {} for partition {}", offset, partition);
1006:             }
1007: 
1008:             applicationEventHandler.addAndGet(new SeekUnvalidatedEvent(
1009:                 defaultApiTimeoutDeadlineMs(),
1010:                 partition,
1011:                 offsetAndMetadata.offset(),
1012:                 offsetAndMetadata.leaderEpoch()
1013:             ));
1014:         } finally {
1015:             release();
1016:         }
1017:     }
