2112:     /**
2113:      * Process the events—if any—that were produced by the {@link ConsumerNetworkThread network thread}.
2114:      * It is possible that {@link ErrorEvent an error}
2115:      * could occur when processing the events. In such cases, the processor will take a reference to the first
2116:      * error, continue to process the remaining events, and then throw the first error that occurred.
2117:      *
2118:      * Visible for testing.
2119:      */
2120:     boolean processBackgroundEvents() {
2121:         AtomicReference<KafkaException> firstError = new AtomicReference<>();
2122: 
2123:         List<BackgroundEvent> events = backgroundEventHandler.drainEvents();
2124:         if (!events.isEmpty()) {
2125:             long startMs = time.milliseconds();
2126:             for (BackgroundEvent event : events) {
2127:                 kafkaConsumerMetrics.recordBackgroundEventQueueTime(time.milliseconds() - event.enqueuedMs());
2128:                 try {
2129:                     if (event instanceof CompletableEvent)
2130:                         backgroundEventReaper.add((CompletableEvent<?>) event);
2131: 
2132:                     backgroundEventProcessor.process(event);
2133:                 } catch (Throwable t) {
2134:                     KafkaException e = ConsumerUtils.maybeWrapAsKafkaException(t);
2135: 
2136:                     if (!firstError.compareAndSet(null, e))
2137:                         log.warn("An error occurred when processing the background event: {}", e.getMessage(), e);
2138:                 }
2139:             }
2140:             kafkaConsumerMetrics.recordBackgroundEventQueueProcessingTime(time.milliseconds() - startMs);
2141:         }
2142: 
2143:         backgroundEventReaper.reap(time.milliseconds());
2144: 
2145:         if (firstError.get() != null)
2146:             throw firstError.get();
2147: 
2148:         return !events.isEmpty();
2149:     }
