1507:     private Timer createTimerForCloseRequests(Duration timeout) {
1508:         // this.time could be null if an exception occurs in constructor prior to setting the this.time field
1509:         final Time time = (this.time == null) ? Time.SYSTEM : this.time;
1510:         return time.timer(Math.min(timeout.toMillis(), requestTimeoutMs));
1511:     }
