1610:     private void commitSync(Optional<Map<TopicPartition, OffsetAndMetadata>> offsets, Duration timeout) {
1611:         acquireAndEnsureOpen();
1612:         long commitStart = time.nanoseconds();
1613:         try {
1614:             SyncCommitEvent syncCommitEvent = new SyncCommitEvent(offsets, calculateDeadlineMs(time, timeout));
1615:             CompletableFuture<Map<TopicPartition, OffsetAndMetadata>> commitFuture = commit(syncCommitEvent);
1616: 
1617:             Timer requestTimer = time.timer(timeout.toMillis());
1618:             awaitPendingAsyncCommitsAndExecuteCommitCallbacks(requestTimer, true);
1619: 
1620:             wakeupTrigger.setActiveTask(commitFuture);
1621:             Map<TopicPartition, OffsetAndMetadata> committedOffsets = ConsumerUtils.getResult(commitFuture, requestTimer);
1622:             interceptors.onCommit(committedOffsets);
1623:         } finally {
1624:             wakeupTrigger.clearTask();
1625:             kafkaConsumerMetrics.recordCommitSync(time.nanoseconds() - commitStart);
1626:             release();
1627:         }
1628:     }
