645:         return index
646:                 .getAnnotations(DotName.createSimple(PermissionsAllowed.class))
647:                 .stream()
648:                 .flatMap(t -> getMethods(t, index))
649:                 .map(e -> createUniqueMethodReference(e.getKey().classInfo(), e.getKey().method()))
650:                 .distinct()
651:                 .toList();
