1154:     private Stream<? extends InputStream> loadResources(String path, List<Pattern> ignorePatterns) {
1155:         Spliterator<URL> resources;
1156: 
1157:         try {
1158:             var resourceEnum = Thread.currentThread().getContextClassLoader().getResources(path).asIterator();
1159:             resources = Spliterators.spliteratorUnknownSize(resourceEnum, Spliterator.IMMUTABLE);
1160:         } catch (IOException ex) {
1161:             throw new UncheckedIOException("Exception processing resources for path " + path, ex);
1162:         }
1163: 
1164:         return StreamSupport.stream(resources, false)
1165:                 .filter(url -> !shouldIgnore(ignorePatterns, url.toString()))
1166:                 .map(url -> loadResource(path, url))
1167:                 .filter(Objects::nonNull);
1168:     }
