1201:     private List<String> getResourceFiles(Path resourcePath, Path target) {
1202:         final String resourceName = ClassPathUtils.toResourceName(resourcePath);
1203:         List<String> filenames = new ArrayList<>();
1204:         // Here we are resolving the resource dir relative to the classes dir and if it does not exist, we fall back to locating the resource dir on the classpath.
1205:         // Although the classes dir should already be on the classpath.
1206:         // In a QuarkusUnitTest the module's classes dir and the test application root could be different directories, is this code here for that reason?
1207:         final Path targetResourceDir = target == null ? null : target.resolve("classes").resolve(resourcePath);
1208:         if (targetResourceDir != null && Files.exists(targetResourceDir)) {
1209:             try (Stream<Path> paths = Files.list(targetResourceDir)) {
1210:                 return paths.map(t -> resourceName + "/" + t.getFileName().toString()).toList();
1211:             } catch (IOException e) {
1212:                 throw new UncheckedIOException("An error occurred while processing " + resourcePath, e);
1213:             }
1214:         } else {
1215:             ClassLoader cl = Thread.currentThread().getContextClassLoader();
1216:             // QuarkusClassLoader will return a ByteArrayInputStream of directory entry names
1217:             try (InputStream inputStream = cl.getResourceAsStream(resourceName)) {
1218:                 if (inputStream != null) {
1219:                     try (BufferedReader br = new BufferedReader(new InputStreamReader(inputStream))) {
1220:                         String resource;
1221:                         while ((resource = br.readLine()) != null) {
1222:                             filenames.add(resourceName + "/" + resource);
1223:                         }
1224:                     }
1225:                 }
1226:             } catch (IOException e) {
1227:                 throw new UncheckedIOException("An error occurred while processing " + resourcePath, e);
1228:             }
1229:         }
1230:         return filenames;
1231:     }
