465:     private List<String> getUserDefinedFilters(IndexView index, OpenApiFilter.RunStage stage) {
466:         EnumSet<OpenApiFilter.RunStage> stages = EnumSet.of(OpenApiFilter.RunStage.BOTH, stage);
467:         Comparator<Object> comparator = Comparator
468:                 .comparing(x -> ((AnnotationInstance) x).valueWithDefault(index, "priority").asInt())
469:                 .reversed();
470:         return index
471:                 .getAnnotations(OpenApiFilter.class)
472:                 .stream()
473:                 .filter(ai -> stages.contains(OpenApiFilter.RunStage.valueOf(ai.valueWithDefault(index).asEnum())))
474:                 .sorted(comparator)
475:                 .map(ai -> ai.target().asClass())
476:                 .filter(c -> c.interfaceNames().contains(DotName.createSimple(OASFilter.class.getName())))
477:                 .map(c -> c.name().toString())
478:                 .collect(Collectors.toCollection(ArrayList::new));
479:     }
