488:     private Optional<AutoSecurityFilter> getAutoSecurityFilter(List<SecurityInformationBuildItem> securityInformationBuildItems,
489:             SmallRyeOpenApiConfig config) {
490: 
491:         if (config.securityScheme().isPresent()) {
492:             return Optional.empty();
493:         }
494: 
495:         // Auto add a security from security extension(s)
496:         return Optional.ofNullable(securityInformationBuildItems)
497:                 .map(Collection::stream)
498:                 .orElseGet(Stream::empty)
499:                 .map(securityInfo -> {
500:                     switch (securityInfo.getSecurityModel()) {
501:                         case jwt:
502:                             return new AutoBearerTokenSecurityFilter(
503:                                     config.securitySchemeName(),
504:                                     config.securitySchemeDescription(),
505:                                     config.getValidSecuritySchemeExtensions(),
506:                                     config.jwtSecuritySchemeValue(),
507:                                     config.jwtBearerFormat());
508:                         case oauth2:
509:                             return new AutoBearerTokenSecurityFilter(
510:                                     config.securitySchemeName(),
511:                                     config.securitySchemeDescription(),
512:                                     config.getValidSecuritySchemeExtensions(),
513:                                     config.oauth2SecuritySchemeValue(),
514:                                     config.oauth2BearerFormat());
515:                         case basic:
516:                             return new AutoBasicSecurityFilter(
517:                                     config.securitySchemeName(),
518:                                     config.securitySchemeDescription(),
519:                                     config.getValidSecuritySchemeExtensions(),
520:                                     config.basicSecuritySchemeValue());
521:                         case oidc:
522:                             // This needs to be a filter in runtime as the config we use to autoconfigure is in runtime
523:                             return securityInfo.getOpenIDConnectInformation()
524:                                     .map(info -> {
525:                                         AutoUrl openIdConnectUrl = new AutoUrl(
526:                                                 config.oidcOpenIdConnectUrl().orElse(null),
527:                                                 info.getUrlConfigKey(),
528:                                                 "/.well-known/openid-configuration");
529: 
530:                                         return new OpenIDConnectSecurityFilter(
531:                                                 config.securitySchemeName(),
532:                                                 config.securitySchemeDescription(),
533:                                                 config.getValidSecuritySchemeExtensions(),
534:                                                 openIdConnectUrl);
535:                                     })
536:                                     .orElse(null);
537:                         default:
538:                             return null;
539:                     }
540:                 })
541:                 .filter(Objects::nonNull)
542:                 .findFirst();
543:     }
