568:     private OASFilter getOperationFilter(OpenApiFilteredIndexViewBuildItem indexViewBuildItem,
569:             LaunchModeBuildItem launchMode,
570:             SmallRyeOpenApiConfig config) {
571: 
572:         Map<String, ClassAndMethod> classNamesMethods = Collections.emptyMap();
573:         Map<String, List<String>> rolesAllowedMethods = Collections.emptyMap();
574:         List<String> authenticatedMethods = Collections.emptyList();
575: 
576:         if (config.autoAddTags() || config.autoAddOperationSummary()) {
577:             classNamesMethods = getClassNamesMethodReferences(indexViewBuildItem);
578:         }
579: 
580:         if (securityConfig(launchMode, config::autoAddSecurityRequirement)) {
581:             rolesAllowedMethods = getRolesAllowedMethodReferences(indexViewBuildItem);
582: 
583:             for (String methodRef : getPermissionsAllowedMethodReferences(indexViewBuildItem)) {
584:                 rolesAllowedMethods.putIfAbsent(methodRef, List.of());
585:             }
586: 
587:             authenticatedMethods = getAuthenticatedMethodReferences(indexViewBuildItem);
588:         }
589: 
590:         if (!classNamesMethods.isEmpty() || !rolesAllowedMethods.isEmpty() || !authenticatedMethods.isEmpty()) {
591:             return new OperationFilter(classNamesMethods, rolesAllowedMethods, authenticatedMethods,
592:                     config.securitySchemeName(),
593:                     config.autoAddTags(), config.autoAddOperationSummary(), config.autoAddBadRequestResponse(),
594:                     isOpenApi_3_1_0_OrGreater(config));
595:         }
596: 
597:         return null;
598:     }
