600:     private OASFilter getAutoServerFilter(SmallRyeOpenApiConfig config, boolean defaultFlag, String description) {
601:         if (config.autoAddServer().orElse(defaultFlag)) {
602:             Config c = ConfigProvider.getConfig();
603: 
604:             String scheme = "http";
605:             String host = c.getOptionalValue("quarkus.http.host", String.class).orElse("0.0.0.0");
606:             int port;
607: 
608:             String insecure = c.getOptionalValue("quarkus.http.insecure-requests", String.class).orElse("enabled");
609:             if (insecure.equalsIgnoreCase("enabled")) {
610:                 port = c.getOptionalValue("quarkus.http.port", Integer.class).orElse(8080);
611:             } else {
612:                 scheme = "https";
613:                 port = c.getOptionalValue("quarkus.http.ssl-port", Integer.class).orElse(8443);
614:             }
615: 
616:             return new AutoServerFilter(scheme, host, port, description);
617:         }
618:         return null;
619:     }
