665:     private static Stream<Map.Entry<ClassAndMethod, AnnotationInstance>> getMethods(AnnotationInstance annotation,
666:             IndexView index) {
667:         if (annotation.target().kind() == Kind.METHOD) {
668:             MethodInfo method = annotation.target().asMethod();
669: 
670:             if (isValidOpenAPIMethodForAutoAdd(method)) {
671:                 return Stream.of(Map.entry(new ClassAndMethod(method.declaringClass(), method), annotation));
672:             }
673:         } else if (annotation.target().kind() == Kind.CLASS) {
674:             ClassInfo classInfo = annotation.target().asClass();
675:             List<MethodInfo> methods = getMethods(classInfo, index);
676:             return methods
677:                     .stream()
678:                     // drop methods that specify the annotation directly
679:                     .filter(method -> !method.hasDeclaredAnnotation(annotation.name()))
680:                     .filter(method -> isValidOpenAPIMethodForAutoAdd(method))
681:                     .map(method -> {
682:                         final ClassInfo resourceClass;
683: 
684:                         if (method.declaringClass().isInterface()) {
685:                             /*
686:                              * smallrye-open-api processes interfaces as the resource class as long as
687:                              * there is a concrete implementation available. Using the interface method's
688:                              * declaring class here allows us to match on the hash that will be set by
689:                              * #handleOperation during scanning.
690:                              */
691:                             resourceClass = method.declaringClass();
692:                         } else {
693:                             resourceClass = classInfo;
694:                         }
695: 
696:                         return Map.entry(new ClassAndMethod(resourceClass, method), annotation);
697:                     });
698:         }
699: 
700:         return Stream.empty();
701:     }
