754:     private static boolean isValidOpenAPIMethodForAutoAdd(MethodInfo method) {
755:         return isOpenAPIEndpoint(method) && !method.hasAnnotation(OPENAPI_SECURITY_REQUIREMENT)
756:                 && method.declaringClass().declaredAnnotation(OPENAPI_SECURITY_REQUIREMENT) == null;
757:     }
