766:     @BuildStep
767:     public void registerOpenApiSchemaClassesForReflection(BuildProducer<ReflectiveClassBuildItem> reflectiveClass,
768:             BuildProducer<ReflectiveHierarchyBuildItem> reflectiveHierarchy,
769:             OpenApiFilteredIndexViewBuildItem openApiFilteredIndexViewBuildItem,
770:             Capabilities cap) {
771: 
772:         FilteredIndexView index = openApiFilteredIndexViewBuildItem.getIndex();
773: 
774:         if (shouldScanAnnotations(cap, index)) {
775:             // Generate reflection declaration from MP OpenAPI Schema definition
776:             // They are needed for serialization.
777:             Collection<AnnotationInstance> schemaAnnotationInstances = index.getAnnotations(OPENAPI_SCHEMA);
778:             for (AnnotationInstance schemaAnnotationInstance : schemaAnnotationInstances) {
779:                 AnnotationTarget typeTarget = schemaAnnotationInstance.target();
780:                 if (typeTarget.kind() != AnnotationTarget.Kind.CLASS) {
781:                     continue;
782:                 }
783:                 produceReflectiveHierarchy(reflectiveHierarchy, Type.create(typeTarget.asClass().name(), Type.Kind.CLASS),
784:                         getClass().getSimpleName() + " > " + typeTarget.asClass().name());
785:             }
786: 
787:             // Generate reflection declaration from MP OpenAPI APIResponse schema definition
788:             // They are needed for serialization
789:             Collection<AnnotationInstance> apiResponseAnnotationInstances = index.getAnnotations(OPENAPI_RESPONSE);
790:             registerReflectionForApiResponseSchemaSerialization(reflectiveClass, reflectiveHierarchy,
791:                     apiResponseAnnotationInstances);
792: 
793:             // Generate reflection declaration from MP OpenAPI APIResponses schema definition
794:             // They are needed for serialization
795:             Collection<AnnotationInstance> apiResponsesAnnotationInstances = index.getAnnotations(OPENAPI_RESPONSES);
796:             for (AnnotationInstance apiResponsesAnnotationInstance : apiResponsesAnnotationInstances) {
797:                 AnnotationValue apiResponsesAnnotationValue = apiResponsesAnnotationInstance.value();
798:                 if (apiResponsesAnnotationValue == null) {
799:                     continue;
800:                 }
801:                 registerReflectionForApiResponseSchemaSerialization(reflectiveClass, reflectiveHierarchy,
802:                         Arrays.asList(apiResponsesAnnotationValue.asNestedArray()));
803:             }
804:         }
805:     }
806: 
807:     private static boolean isOpenAPIEndpoint(MethodInfo method) {
808:         Set<DotName> httpAnnotations = getAllOpenAPIEndpoints();
809:         for (DotName httpAnnotation : httpAnnotations) {
810:             if (method.hasAnnotation(httpAnnotation)) {
811:                 return true;
812:             }
813:         }
814:         return false;
815:     }
816: 
817:     private static List<MethodInfo> getMethods(ClassInfo declaringClass, IndexView index) {
818:         List<MethodInfo> methods = new ArrayList<>();
819:         methods.addAll(declaringClass.methods());
820: 
821:         // Check if the method overrides a method from an interface
822:         for (Type interfaceType : declaringClass.interfaceTypes()) {
823:             ClassInfo interfaceClass = index.getClassByName(interfaceType.name());
824:             if (interfaceClass != null) {
825:                 for (MethodInfo interfaceMethod : interfaceClass.methods()) {
826:                     methods.add(interfaceMethod);
827:                 }
828:             }
829:         }
830: 
831:         DotName superClassName = declaringClass.superName();
832:         if (superClassName != null) {
833:             ClassInfo superClass = index.getClassByName(superClassName);
834: 
835:             if (superClass != null) {
836:                 methods.addAll(getMethods(superClass, index));
837:             }
838:         }
839: 
840:         return methods;
841:     }
842: 
843:     private static Set<DotName> getAllOpenAPIEndpoints() {
844:         Set<DotName> httpAnnotations = new HashSet<>();
845:         httpAnnotations.addAll(JaxRsConstants.HTTP_METHODS);
846:         httpAnnotations.addAll(SpringConstants.HTTP_METHODS);
847:         return httpAnnotations;
848:     }
