1038:     private void storeGeneratedSchema(Path directory, String filename, OutputTargetBuildItem out, String schemaDocument,
1039:             String format)
1040:             throws IOException {
1041:         Path outputDirectory = out.getOutputDirectory();
1042: 
1043:         if (!directory.isAbsolute() && outputDirectory != null) {
1044:             var baseDir = outputDirectory.getParent();
1045:             // check if outputDirectory is the root of the filesystem
1046:             if (baseDir == null) {
1047:                 baseDir = outputDirectory;
1048:             }
1049:             directory = baseDir.resolve(directory);
1050:         }
1051: 
1052:         if (!Files.exists(directory)) {
1053:             Files.createDirectories(directory);
1054:         }
1055: 
1056:         Path file = directory.resolve(filename + "." + format);
1057:         if (!Files.exists(file)) {
1058:             Files.createFile(file);
1059:         }
1060: 
1061:         Files.writeString(file, schemaDocument, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
1062:         log.info("OpenAPI " + format + " saved: " + file.toString());
1063:     }
