1065:     private boolean shouldScanAnnotations(Capabilities capabilities, IndexView index) {
1066:         // Disabled via config
1067:         Config config = ConfigProvider.getConfig();
1068:         boolean scanDisable = config.getOptionalValue(OASConfig.SCAN_DISABLE, Boolean.class).orElse(false);
1069:         if (scanDisable) {
1070:             return false;
1071:         }
1072: 
1073:         // Only scan if either RESTEasy, Quarkus REST, Spring Web or Vert.x Web (with @Route) is used
1074:         boolean isRestEasy = capabilities.isPresent(Capability.RESTEASY);
1075:         boolean isQuarkusRest = capabilities.isPresent(Capability.RESTEASY_REACTIVE);
1076:         boolean isSpring = capabilities.isPresent(Capability.SPRING_WEB);
1077:         boolean isVertx = isUsingVertxRoute(index);
1078:         return isRestEasy || isQuarkusRest || isSpring || isVertx;
1079:     }
