1086:     private InputStream loadAdditionalDocsModel(SmallRyeOpenApiConfig openApiConfig, List<Pattern> ignorePatterns,
1087:             Path target) {
1088:         if (openApiConfig.ignoreStaticDocument()) {
1089:             return null;
1090:         }
1091: 
1092:         SmallRyeOpenAPI.Builder staticBuilder = SmallRyeOpenAPI.builder()
1093:                 .withConfig(ConfigProvider.getConfig())
1094:                 .enableModelReader(false)
1095:                 .enableStandardStaticFiles(false)
1096:                 .enableAnnotationScan(false)
1097:                 .enableStandardFilter(false);
1098: 
1099:         return openApiConfig.additionalDocsDirectory()
1100:                 .map(Collection::stream)
1101:                 .orElseGet(Stream::empty)
1102:                 .map(path -> getResourceFiles(path, target))
1103:                 .flatMap(Collection::stream)
1104:                 .filter(path -> path.endsWith(".json") || path.endsWith(".yaml") || path.endsWith(".yml"))
1105:                 .flatMap(path -> loadResources(path, ignorePatterns))
1106:                 .map(stream -> staticBuilder.withCustomStaticFile(() -> stream).build().model())
1107:                 .reduce(MergeUtil::merge)
1108:                 .map(mergedModel -> staticBuilder
1109:                         .withInitialModel(mergedModel)
1110:                         .withCustomStaticFile(() -> null)
1111:                         .build()
1112:                         .toJSON())
1113:                 .map(jsonModel -> new ByteArrayInputStream(jsonModel.getBytes(StandardCharsets.UTF_8)))
1114:                 .orElse(null);
1115:     }
