1117:     private Predicate<String> getScannerFilter(Capabilities capabilities, IndexView index) {
1118:         List<String> scanners = new ArrayList<>();
1119:         if (capabilities.isPresent(Capability.RESTEASY) || capabilities.isPresent(Capability.RESTEASY_REACTIVE)) {
1120:             scanners.add(JAX_RS);
1121:         }
1122:         if (capabilities.isPresent(Capability.SPRING_WEB)) {
1123:             scanners.add(SPRING);
1124:         }
1125:         if (isUsingVertxRoute(index)) {
1126:             scanners.add(VERT_X);
1127:         }
1128:         return scanners::contains;
1129:     }
