291:     @BuildStep
292:     public void configurationDescriptorBuilding(
293:             HibernateOrmConfig hibernateOrmConfig,
294:             CombinedIndexBuildItem index,
295:             ImpliedBlockingPersistenceUnitTypeBuildItem impliedPU,
296:             List<PersistenceXmlDescriptorBuildItem> persistenceXmlDescriptors,
297:             List<JdbcDataSourceBuildItem> jdbcDataSources,
298:             ApplicationArchivesBuildItem applicationArchivesBuildItem,
299:             LaunchModeBuildItem launchMode,
300:             JpaModelBuildItem jpaModel,
301:             Capabilities capabilities,
302:             BuildProducer<SystemPropertyBuildItem> systemProperties,
303:             BuildProducer<NativeImageResourceBuildItem> nativeImageResources,
304:             BuildProducer<HotDeploymentWatchedFileBuildItem> hotDeploymentWatchedFiles,
305:             BuildProducer<PersistenceUnitDescriptorBuildItem> persistenceUnitDescriptors,
306:             BuildProducer<ReflectiveMethodBuildItem> reflectiveMethods,
307:             BuildProducer<UnremovableBeanBuildItem> unremovableBeans,
308:             List<DatabaseKindDialectBuildItem> dbKindMetadataBuildItems) {
309: 
310:         if (!hasEntities(jpaModel)) {
311:             // we can bail out early as there are no entities
312:             LOG.warn("Hibernate ORM is disabled because no JPA entities were found");
313:             return;
314:         }
315: 
316:         // First produce the PUs having a persistence.xml: these are not reactive, as we don't allow using a persistence.xml for them.
317:         for (PersistenceXmlDescriptorBuildItem persistenceXmlDescriptorBuildItem : persistenceXmlDescriptors) {
318:             PersistenceUnitDescriptor xmlDescriptor = persistenceXmlDescriptorBuildItem.getDescriptor();
319:             String puName = xmlDescriptor.getName();
320:             Optional<JdbcDataSourceBuildItem> jdbcDataSource = jdbcDataSources.stream()
321:                     .filter(i -> i.isDefault())
322:                     .findFirst();
323:             collectDialectConfigForPersistenceXml(puName, xmlDescriptor);
324:             Optional<FormatMapperKind> jsonMapper = jsonMapperKind(capabilities);
325:             Optional<FormatMapperKind> xmlMapper = xmlMapperKind(capabilities);
326:             jsonMapper.flatMap(FormatMapperKind::requiredBeanType)
327:                     .ifPresent(type -> unremovableBeans.produce(UnremovableBeanBuildItem.beanClassNames(type)));
328:             xmlMapper.flatMap(FormatMapperKind::requiredBeanType)
329:                     .ifPresent(type -> unremovableBeans.produce(UnremovableBeanBuildItem.beanClassNames(type)));
330:             persistenceUnitDescriptors
331:                     .produce(new PersistenceUnitDescriptorBuildItem(
332:                             QuarkusPersistenceUnitDescriptor.validateAndReadFrom(xmlDescriptor),
333:                             new RecordedConfig(
334:                                     Optional.of(DataSourceUtil.DEFAULT_DATASOURCE_NAME),
335:                                     jdbcDataSource.map(JdbcDataSourceBuildItem::getDbKind),
336:                                     jdbcDataSource.flatMap(JdbcDataSourceBuildItem::getDbVersion),
337:                                     Optional.ofNullable(xmlDescriptor.getProperties().getProperty(AvailableSettings.DIALECT)),
338:                                     getMultiTenancyStrategy(
339:                                             Optional.ofNullable(persistenceXmlDescriptorBuildItem.getDescriptor()
340:                                                     .getProperties().getProperty("hibernate.multiTenancy"))), //FIXME this property is meaningless in Hibernate ORM 6
341:                                     hibernateOrmConfig.database().ormCompatibilityVersion(), Collections.emptyMap()),
342:                             null,
343:                             jpaModel.getXmlMappings(persistenceXmlDescriptorBuildItem.getDescriptor().getName()),
344:                             true, isHibernateValidatorPresent(capabilities), jsonMapper, xmlMapper));
345:         }
346: 
347:         if (impliedPU.shouldGenerateImpliedBlockingPersistenceUnit()) {
348:             handleHibernateORMWithNoPersistenceXml(hibernateOrmConfig, index, persistenceXmlDescriptors,
349:                     jdbcDataSources, applicationArchivesBuildItem, launchMode.getLaunchMode(), jpaModel, capabilities,
350:                     systemProperties, nativeImageResources, hotDeploymentWatchedFiles, persistenceUnitDescriptors,
351:                     reflectiveMethods, unremovableBeans, dbKindMetadataBuildItems);
352:         }
353:     }
