510:     @SuppressWarnings("unchecked")
511:     @BuildStep
512:     @Record(STATIC_INIT)
513:     public void build(RecorderContext recorderContext, HibernateOrmRecorder recorder,
514:             Capabilities capabilities,
515:             JpaModelBuildItem jpaModel,
516:             List<PersistenceUnitDescriptorBuildItem> persistenceUnitDescriptorBuildItems,
517:             List<HibernateOrmIntegrationStaticConfiguredBuildItem> integrationBuildItems,
518:             BuildProducer<BeanContainerListenerBuildItem> beanContainerListener,
519:             LaunchModeBuildItem launchMode) throws Exception {
520:         validateHibernatePropertiesNotUsed();
521: 
522:         final boolean enableORM = hasEntities(jpaModel);
523:         final boolean hibernateReactivePresent = capabilities.isPresent(Capability.HIBERNATE_REACTIVE);
524:         //The Hibernate Reactive extension is able to handle registration of PersistenceProviders for both reactive and
525:         //traditional blocking Hibernate, by depending on this module and delegating to this code.
526:         //So when the Hibernate Reactive extension is present, trust that it will register its own PersistenceProvider
527:         //which will be responsible to decide which type of ORM to bootstrap.
528:         //But if the extension is not present, we need to register our own PersistenceProvider - even if the ORM is not enabled!
529:         if (!hibernateReactivePresent) {
530:             recorder.callHibernateFeatureInit(enableORM);
531:         }
532: 
533:         if (!enableORM) {
534:             // we can bail out early
535:             return;
536:         }
537: 
538:         recorder.enlistPersistenceUnit(jpaModel.getEntityClassNames());
539: 
540:         final QuarkusScanner scanner = buildQuarkusScanner(jpaModel);
541: 
542:         ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
543:         // inspect service files for additional integrators
544:         Collection<Class<? extends Integrator>> integratorClasses = new LinkedHashSet<>();
545:         for (String integratorClassName : ServiceUtil.classNamesNamedIn(classLoader, INTEGRATOR_SERVICE_FILE)) {
546:             integratorClasses.add((Class<? extends Integrator>) recorderContext.classProxy(integratorClassName));
547:         }
548:         if (launchMode.getLaunchMode() == LaunchMode.DEVELOPMENT) {
549:             integratorClasses.add(HibernateOrmDevIntegrator.class);
550:             integratorClasses.add(SchemaManagementIntegrator.class);
551:         }
552: 
553:         Map<String, List<HibernateOrmIntegrationStaticDescriptor>> integrationStaticDescriptors = HibernateOrmIntegrationStaticConfiguredBuildItem
554:                 .collectDescriptors(integrationBuildItems);
555: 
556:         List<QuarkusPersistenceUnitDefinition> finalStagePUDescriptors = new ArrayList<>();
557:         for (PersistenceUnitDescriptorBuildItem pud : persistenceUnitDescriptorBuildItems) {
558:             finalStagePUDescriptors.add(
559:                     pud.asOutputPersistenceUnitDefinition(integrationStaticDescriptors
560:                             .getOrDefault(pud.getPersistenceUnitName(), Collections.emptyList())));
561:         }
562: 
563:         if (hasXmlMappings(persistenceUnitDescriptorBuildItems)) {
564:             //Make it possible to record JAXBElement as bytecode:
565:             recorderContext.registerSubstitution(JAXBElement.class,
566:                     JAXBElementSubstitution.Serialized.class,
567:                     JAXBElementSubstitution.class);
568:             recorderContext.registerSubstitution(QName.class,
569:                     QNameSubstitution.Serialized.class,
570:                     QNameSubstitution.class);
571:         }
572: 
573:         beanContainerListener
574:                 .produce(new BeanContainerListenerBuildItem(
575:                         recorder.initMetadata(finalStagePUDescriptors, scanner, integratorClasses)));
576:     }
