983:             throw new ConfigurationException(String.format(Locale.ROOT,
984:                     "Datasource must be defined for persistence unit '%s'."
985:                             + " Refer to https://quarkus.io/guides/datasource for guidance.",
986:                     persistenceUnitName),
987:                     new HashSet<>(Arrays.asList("quarkus.datasource.db-kind", "quarkus.datasource.username",
988:                             "quarkus.datasource.password", "quarkus.datasource.jdbc.url")));
