1034:             String dataSourceName = persistenceUnitConfig.datasource().get();
1035:             return Optional.of(jdbcDataSources.stream()
1036:                     .filter(i -> dataSourceName.equals(i.getName()))
1037:                     .findFirst()
1038:                     .orElseThrow(() -> PersistenceUnitUtil.unableToFindDataSource(persistenceUnitName, dataSourceName,
1039:                             DataSourceUtil.dataSourceNotConfigured(dataSourceName))));
