1054:     @SuppressWarnings("deprecation")
1055:     private void enhanceEntities(final JpaModelBuildItem jpaModel,
1056:             BuildProducer<BytecodeTransformerBuildItem> transformers,
1057:             List<AdditionalJpaModelBuildItem> additionalJpaModelBuildItems,
1058:             List<io.quarkus.hibernate.orm.deployment.AdditionalJpaModelBuildItem> deprecatedAdditionalJpaModelBuildItems,
1059:             BuildProducer<GeneratedClassBuildItem> additionalClasses) {
1060:         HibernateEntityEnhancer hibernateEntityEnhancer = new HibernateEntityEnhancer();
1061:         for (String i : jpaModel.getManagedClassNames()) {
1062: 
1063:             transformers.produce(new BytecodeTransformerBuildItem.Builder()
1064:                     .setClassToTransform(i)
1065:                     .setVisitorFunction(hibernateEntityEnhancer)
1066:                     .setCacheable(true).build());
1067:         }
1068:         Set<String> additionalClassNames = new HashSet<>();
1069:         for (AdditionalJpaModelBuildItem additionalJpaModel : additionalJpaModelBuildItems) {
1070:             additionalClassNames.add(additionalJpaModel.getClassName());
1071:         }
1072:         for (io.quarkus.hibernate.orm.deployment.AdditionalJpaModelBuildItem additionalJpaModel : deprecatedAdditionalJpaModelBuildItems) {
1073:             additionalClassNames.add(additionalJpaModel.getClassName());
1074:         }
1075:         for (String className : additionalClassNames) {
1076:             try {
1077:                 byte[] bytes = IoUtil.readClassAsBytes(HibernateOrmProcessor.class.getClassLoader(), className);
1078:                 byte[] enhanced = hibernateEntityEnhancer.enhance(className, bytes);
1079:                 additionalClasses.produce(new GeneratedClassBuildItem(false, className, enhanced != null ? enhanced : bytes));
1080:             } catch (IOException e) {
1081:                 throw new RuntimeException("Failed to read Model class", e);
1082:             }
1083:         }
