1359:             for (String managedClassOrPackageName : managedClassAndPackageNames) {
1360:                 CachedProxy result;
1361:                 if (proxyCache.cache.containsKey(managedClassOrPackageName)
1362:                         && !isModified(managedClassOrPackageName, changedClasses, combinedIndex)) {
1363:                     result = proxyCache.cache.get(managedClassOrPackageName);
