1405:     // Creates a TypePool that is aware of class transformations applied to entity classes,
1406:     // so that ByteBuddy can take these transformations into account.
1407:     // This is especially important when getters/setters are added to entity classes,
1408:     // because we want those methods to be overridden in proxies to trigger proxy initialization.
1409:     private TypePool createTransformedClassesTypePool(TransformedClassesBuildItem transformedClassesBuildItem,
1410:             Set<String> entityClasses) {
1411:         Map<String, byte[]> transformedClasses = new HashMap<>();
1412:         for (Set<TransformedClassesBuildItem.TransformedClass> transformedClassSet : transformedClassesBuildItem
1413:                 .getTransformedClassesByJar().values()) {
1414:             for (TransformedClassesBuildItem.TransformedClass transformedClass : transformedClassSet) {
1415:                 String className = transformedClass.getClassName();
1416:                 if (entityClasses.contains(className)) {
1417:                     transformedClasses.put(className, transformedClass.getData());
1418:                 }
1419:             }
1420:         }
1421:         return TypePool.Default.of(new ClassFileLocator.Compound(
1422:                 new ClassFileLocator.Simple(transformedClasses),
1423:                 ClassFileLocator.ForClassLoader.of(Thread.currentThread().getContextClassLoader())));
1424:     }
