34: /**
35:  * Syntax parser that converts EO code to XMIR (XML-based Intermediate Representation) using ANTLR4.
36:  * EoSyntax parses EO source code, generates a structured XML representation, and applies a series
37:  * of transformations to produce canonical XMIR.
38:  *
39:  * <p>The parsing process includes lexical analysis, syntax analysis, and XML transformation:
40:  * 1. EO code is first processed by the EoIndentLexer
41:  * 2. Then parsed by ANTLR-generated parser
42:  * 3. Finally transformed into XMIR through a series of XSL transformations</p>
43:  *
44:  * <p>Usage examples:</p>
45:  *
46:  * <p>1. Parse EO code from a string:</p>
47:  * <pre>
48:  * XML xmir = new EoSyntax("[args] > app\n  42 > @").parsed();
49:  * </pre>
50:  *
51:  * <p>2. Parse EO code from a file:</p>
52:  * <pre>
53:  * XML xmir = new EoSyntax(
54:  *     new InputOf(new File("src/main/eo/fibonacci.eo"))
55:  * ).parsed();
56:  * </pre>
57:  *
58:  * <p>3. Parse with custom transformations:</p>
59:  * <pre>
60:  * XML xmir = new EoSyntax(
61:  *     "[x] > f\n  x > @",
62:  *     new TrClasspath<>(
63:  *         "/org/eolang/parser/pack/validation.xsl",
64:  *         "/org/eolang/parser/pack/transform.xsl"
65:  *     )
66:  * ).parsed();
67:  * </pre>
68:  *
69:  * <p>After parsing, errors can be found in the XML at the "/object/errors" XPath.
70:  * If no errors are present, the parsed program is valid EO code.</p>
71:  *
72:  * @since 0.1
73:  * @checkstyle ClassFanOutComplexityCheck (500 lines)
74:  */
75: public final class EoSyntax implements Syntax {
76:     /**
77:      * Set of optimizations that builds canonical XMIR from parsed EO.
78:      * @todo #3807:90min Refactor EoSyntax transformations to make them less coupled.
79:      *  Currently most of these transformations are strongly coupled.
80:      *  For example, `stars-to-tuples`, `StHex` and `explicit-data` are
81:      *  dependent on each other. Moreover, the order of transformations
82:      *  matters. We need to refactor these transformations to make them
83:      *  more independent and order-agnostic if possible.
84:      */
85:     private static final Function<XML, XML> CANONICAL = new Xsline(
86:         new TrFull(
87:             new TrJoined<>(
88:                 new TrClasspath<>(
89:                     "/org/eolang/parser/parse/move-voids-up.xsl",
90:                     "/org/eolang/parser/parse/validate-before-stars.xsl",
91:                     "/org/eolang/parser/parse/resolve-before-stars.xsl",
92:                     "/org/eolang/parser/parse/wrap-method-calls.xsl",
93:                     "/org/eolang/parser/parse/const-to-dataized.xsl",
94:                     "/org/eolang/parser/parse/stars-to-tuples.xsl",
95:                     "/org/eolang/parser/parse/vars-float-up.xsl",
96:                     "/org/eolang/parser/parse/validate-objects-count.xsl",
97:                     "/org/eolang/parser/parse/build-fqns.xsl",
98:                     "/org/eolang/parser/parse/expand-qqs.xsl",
99:                     "/org/eolang/parser/parse/expand-aliases.xsl",
100:                     "/org/eolang/parser/parse/resolve-aliases.xsl",
101:                     "/org/eolang/parser/parse/add-default-package.xsl",
102:                     "/org/eolang/parser/parse/roll-bases.xsl",
103:                     "/org/eolang/parser/parse/cti-adds-errors.xsl",
104:                     "/org/eolang/parser/parse/decorate.xsl"
105:                 ).back(),
106:                 new TrDefault<>(new StHex())
107:             )
108:         )
109:     )::pass;
110: 
111:     /**
112:      * Text to parse.
113:      */
114:     private final Input input;
115: 
116:     /**
117:      * Transform XMIR after parsing.
118:      */
119:     private final Function<XML, XML> transform;
120: 
121:     /**
122:      * Ctor.
123:      * @param ipt The EO program to parse
124:      */
125:     public EoSyntax(final String ipt) {
126:         this(new InputOf(ipt));
127:     }
128: 
129:     /**
130:      * Ctor.
131:      * @param ipt The EO program to parse
132:      * @param transform Transform XMIR after parsing
133:      */
134:     public EoSyntax(final String ipt, final Train<Shift> transform) {
135:         this(new InputOf(ipt), transform);
136:     }
137: 
138:     /**
139:      * Ctor.
140:      * @param ipt The EO program to parse
141:      */
142:     public EoSyntax(final Input ipt) {
143:         this(ipt, EoSyntax.CANONICAL);
144:     }
145: 
146:     /**
147:      * Ctor for testing.
148:      * @param ipt The EO program to parse
149:      * @param transform Transform XMIR after parsing train
150:      */
151:     EoSyntax(final Input ipt, final Train<Shift> transform) {
152:         this(ipt, new Xsline(transform)::pass);
153:     }
154: 
155:     /**
156:      * Ctor.
157:      * @param ipt The EO program to parse
158:      * @param transform Transform XMIR after parsing function
159:      */
160:     EoSyntax(final Input ipt, final Function<XML, XML> transform) {
161:         this.input = ipt;
162:         this.transform = transform;
163:     }
164: 
165:     /**
166:      * Compile it to XML and save.
167:      *
168:      * <p>No exception will be thrown if the syntax is invalid. In any case, XMIR will
169:      * be generated and saved. Read it in order to find the errors,
170:      * at <tt>/object/errors</tt> XPath.</p>
171:      *
172:      * @return Parsed XML
173:      * @throws IOException If fails
174:      */
175:     public XML parsed() throws IOException {
176:         final List<Text> lines = this.lines();
177:         final GeneralErrors spy = new GeneralErrors(lines);
178:         final EoLexer lexer = new EoIndentLexer(this.normalize());
179:         lexer.removeErrorListeners();
180:         lexer.addErrorListener(spy);
181:         final EoParser parser = new EoParser(
182:             new CommonTokenStream(lexer)
183:         );
184:         parser.removeErrorListeners();
185:         final EoParserErrors eospy = new EoParserErrors(lines);
186:         parser.addErrorListener(eospy);
187:         final XeEoListener xel = new XeEoListener();
188:         new ParseTreeWalker().walk(xel, parser.program());
189:         final XML dom = this.transform.apply(
190:             new XMLDocument(
191:                 new Xembler(
192:                     new Directives(xel).append(new DrErrors(spy)).append(new DrErrors(eospy))
193:                 ).domQuietly()
194:             )
195:         );
196:         final long errors = new Unchecked<>(new LengthOf(spy)).value()
197:             + new Unchecked<>(new LengthOf(eospy)).value();
198:         if (errors == 0) {
199:             Logger.debug(
200:                 this,
201:                 "The program of %d EO lines compiled, no errors",
202:                 lines.size()
203:             );
204:         } else {
205:             Logger.debug(
206:                 this, "The %s program of %d EO lines compiled with %d error(s)",
207:                 lines.size(), errors
208:             );
209:         }
210:         return dom;
211:     }
212: 
213:     /**
214:      * Normalize input to UNIX format to ensure that EOL exists at the
215:      * end of the text.
216:      *
217:      * @return UNIX formatted text.
218:      */
219:     private Text normalize() {
220:         return new FormattedText(
221:             "%s\n",
222:             new Joined(new TextOf("\n"), this.lines())
223:         );
224:     }
225: 
226:     /**
227:      * Split input into lines.
228:      * @return Lines without line breaks.
229:      */
230:     private List<Text> lines() {
231:         return new ListOf<>(new Split(new TextOf(this.input), "\r?\n"));
232:     }
233: }
